OA_MAIN_PREVIEW("ExampleVisionImage") {
	auto sourceResult = oa::FnImage::decodeFile(
		oa::Paths::asset("image/coverVision.jpg"), oa::ImageFormat::Rgb);
	if (not sourceResult.isOk()) return 1;
	auto source = std::move(sourceResult).getValue();

	auto grayscale = oa::FnImage::grayscale(source);

	const oa::Path output = oa::Paths::var("example/vision/coverVisionGrayscale.jpg");
	if (not oa::Filesystem::createDirectories(output.parentPath()).isOk()) return 1;
	if (not oa::FnImage::saveFile(output, grayscale, 92U).isOk()) return 1;

	if (not grayscale.validate()) return 1;
	if (grayscale.width() != 1672 or grayscale.height() != 941) return 1;
	if (grayscale.format() != oa::ImageFormat::Gray) return 1;
	if (not oa::Filesystem::isFile(output)) return 1;

	std::printf("Saved grayscale image: %s\n", output.cStr());

	if (argc > 1 and oa::StringView(argv[1]) == "--preview") {
		oa::ViewerConfig previewConfig;
		previewConfig.mode = oa::ViewerMode::Image;
		previewConfig.title = "OA vision · grayscale cover";
		previewConfig.width = 1280U;
		previewConfig.height = 646U;
		if (not oa::Viewer::preview(engine, oa::Paths::var("example/vision/coverVisionGrayscale.jpg").string(),
			previewConfig).isOk()) {
			return 1;
		}
	}
	return 0;
}

#include <oa/oa.h>

#include <array>
#include <cstring>
#include <cstdio>
#include <utility>

OA_MAIN("ExampleCryptoShake256") {
	constexpr std::array<oa::U8, 15> messagesBytes{
		97U, 108U, 112U, 104U, 97U, 98U, 114U, 97U, 118U, 111U, 99U, 114U, 121U, 112U, 116U
	};
	auto messages = oa::FnMatrix::fromBytes(
		oa::Span<const oa::U8>(messagesBytes.data(), messagesBytes.size()),
		{3, 5},
		oa::ScalarType::UInt8);

	auto digests = oa::FnHash::shake256(messages, 32U);

	std::array<oa::U8, 96> gpu{};
	std::array<oa::U8, 96> cpu{};
	if (not oa::FnMatrix::copyToHost(digests, gpu.data(), gpu.size()).isOk()) return 1;
	for (oa::Usize row = 0; row < 3U; ++row) {
		oa::shake256(
			messagesBytes.data() + row * 5U, 5U,
			cpu.data() + row * 32U, 32U);
	}
	if (std::memcmp(gpu.data(), cpu.data(), gpu.size()) != 0) return 1;

	std::puts("3 GPU SHAKE-256 digests match the CPU oracle");
	return 0;
}

#include <oa/oa.h>

#include <array>
#include <cstdio>
#include <utility>

OA_MAIN_MODE("ExamplePlotLine", argc > 1 and oa::StringView(argv[1]) == "--preview" ? oa::PresentationMode::Swapchain : oa::PresentationMode::Headless) {
	oa::plot::Figure figure({
		.title = "Training loss",
		.width = 960U,
		.height = 540U,
		.theme = oa::plot::Theme::Dark,
	});
	constexpr std::array<oa::F32, 6> figureValues{
		1.0F, 0.72F, 0.51F, 0.38F, 0.29F, 0.23F
	};
	figure.ax(0, 0).xLabel("step");
	figure.ax(0, 0).yLabel("loss");
	figure.ax(0, 0).plot(figureValues);

	auto renderedResult = figure.render(engine);
	if (not renderedResult.isOk()) return 1;
	auto rendered = std::move(renderedResult).getValue();

	const oa::Path output = oa::Paths::var("example/ui/trainingLoss.jpg");
	if (not oa::Filesystem::createDirectories(output.parentPath()).isOk()) return 1;
	if (not oa::FnImage::saveFile(output, rendered, 92U).isOk()) return 1;

	if (not rendered.validate()) return 1;
	if (rendered.width() != 960 or rendered.height() != 540) return 1;
	if (rendered.format() != oa::ImageFormat::Rgba) return 1;
	if (not oa::Filesystem::isFile(output)) return 1;

	std::printf("Saved training-loss plot: %s\n", output.cStr());

	if (argc > 1 and oa::StringView(argv[1]) == "--preview") {
		oa::ViewerConfig previewConfig;
		previewConfig.mode = oa::ViewerMode::Image;
		previewConfig.title = "OA plot · training loss";
		previewConfig.width = 1280U;
		previewConfig.height = 646U;
		if (not oa::Viewer::preview(engine, oa::Paths::var("example/ui/trainingLoss.jpg").string(),
			previewConfig).isOk()) {
			return 1;
		}
	}
	return 0;
}
